package com.tiny.snake;import android.app.Activity;import android.content.Context;import android.graphics.*;import android.os.*;import android.view.*;import java.util.Random;public class MainActivity extends Activity{@Override protected void onCreate(Bundle b){super.onCreate(b);requestWindowFeature(1);getWindow().setFlags(1024,1024);setContentView(new V(this));}private class V extends View{int[]x=new int[400],y=new int[400];int l=3,X=1,Y=0,f,g,c=15,r=15;Paint p=new Paint();Handler h=new Handler();Random R=new Random();float s,t;public V(Context k){super(k);P();h.postDelayed(new Runnable(){public void run(){if(c>0&&r>0){for(int i=l-1;i>0;i--){x[i]=x[i-1];y[i]=y[i-1];}x[0]+=X;y[0]+=Y;boolean d=x[0]<=0||x[0]>=c-1||y[0]<=0||y[0]>=r-1;for(int i=1;i<l;i++)if(x[0]==x[i]&&y[0]==y[i])d=true;if(d){l=3;X=1;Y=0;x[0]=5;y[0]=5;P();}else if(x[0]==f&&y[0]==g){l++;P();}}invalidate();h.postDelayed(this,150);}},150);}void P(){f=1+R.nextInt(c-2);g=1+R.nextInt(r-2);}@Override protected void onDraw(Canvas C){C.drawColor(-16777216);int w=getWidth(),H=getHeight();if(w==0||H==0)return;int z=w/c;r=H/z;p.setColor(-7829368);for(int i=0;i<c;i++){C.drawRect(i*z,0,(i+1)*z,z,p);C.drawRect(i*z,(r-1)*z,(i+1)*z,r*z,p);}for(int j=0;j<r;j++){C.drawRect(0,j*z,z,(j+1)*z,p);C.drawRect((c-1)*z,j*z,c*z,(j+1)*z,p);}p.setColor(-65536);C.drawRect(f*z,g*z,(f+1)*z,(g+1)*z,p);p.setColor(-16711936);for(int i=0;i<l;i++)C.drawRect(x[i]*z,y[i]*z,(x[i]+1)*z,(y[i]+1)*z,p);p.setColor(-1);p.setTextSize(35);p.setTextAlign(Paint.Align.CENTER);C.drawText("Score: "+(l-3),w/2,z-5,p);}@Override public boolean onTouchEvent(MotionEvent e){if(e.getAction()==0){s=e.getX();t=e.getY();}else if(e.getAction()==1){float u=e.getX()-s,v=e.getY()-t;if(Math.abs(u)>Math.abs(v)){if(Math.abs(u)>30&&X==0){X=u>0?1:-1;Y=0;}}else if(Math.abs(v)>30&&Y==0){X=0;Y=v>0?1:-1;}}return true;}}}
